import sys
from collections import defaultdict, deque

def main():
    input = sys.stdin.read().split()
    n = int(input[0])
    edges = [(int(input[i*2+1]), int(input[i*2+2])) for i in range(n)]

    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    def find_ringroad(graph, n):
        visited = [False] * (n + 1)
        parent = [-1] * (n + 1)
        stack = []

        def dfs(node, p):
            visited[node] = True
            stack.append(node)
            for neighbor in graph[node]:
                if not visited[neighbor]:
                    parent[neighbor] = node
                    if dfs(neighbor, node):
                        return True
                elif neighbor != p and parent[node] != neighbor:
                    while stack[-1] != neighbor:
                        stack.pop()
                    return True
            stack.pop()
            return False

        for i in range(1, n + 1):
            if not visited[i]:
                if dfs(i, -1):
                    break

        ringroad = set(stack)
        return ringroad

    ringroad = find_ringroad(graph, n)
    distances = [0] * (n + 1)
    queue = deque(ringroad)

    while queue:
        current = queue.popleft()
        for neighbor in graph[current]:
            if distances[neighbor] == 0 and neighbor not in ringroad:
                distances[neighbor] = distances[current] + 1
                queue.append(neighbor)

    print(' '.join(map(str, distances[1:])))
main()
